globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-22 10:59:01 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"AIが数学の未解決問題「リーマン予想」を証明か　米アンソロピックの数学者が主張 - BBCニュース","url":"https://www.bbc.com/japanese/articles/cwlyl6ymz841o","source":"Hatena","published_at":"2026-11-21 13:22","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"アンソロピックの数学者がAI「Claude」を用いてリーマン予想を証明したと主張","summary":"アンソロピック所属の数学者が、同社のAI「Claude」を使用して数学の難問「リーマン予想」を証明したと発表しました。6週間で証明を完了したとし、Lean言語で記述された25万ページに及ぶ証明を公開しています。\n\nこの主張が正しければ歴史的な快挙となりますが、専門家からは検証に時間がかかるという慎重な声も上がっています。AIによる数学的証明の是非や、学術界への影響について議論を呼んでいます。","importance":10},{"title":"情報漏えいを公表しないリスクの要点整理 - Qiita","url":"https://qiita.com/Maruo110/items/385b2c7ef5fbd074e6e2","source":"Hatena","published_at":"2026-11-22 07:25","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"情報漏えい公表の義務とリスク：隠蔽が招くさらなる信頼失墜","summary":"個人情報保護委員会への報告義務化により漏えい件数は可視化されたが、世間への公表は義務ではない。しかし、ランサムウェアによる二重恐喝（リークサイトでのデータ公開）が常態化する現在、「公表しない」という選択はリスク回避ではなく、攻撃者に公開の主導権を委ねる行為となる。\n\n漏えいそのものよりも「隠蔽していた事実」が後に発覚した際の社会的制裁が大きくなるリスクを認識し、広報・法務・経営層を含めた事前の公表基準策定が不可欠である。","importance":8},{"title":"月3,000回の無料枠で、「AIに任せないこと」を先に決めた。猫耳秘書と宇宙を旅した話","url":"https://zenn.dev/nanako1129/articles/799de43c4e556c","source":"Zenn","published_at":"2026-11-22 00:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"無料枠でAIをゲームに組み込む：体験を損なわない役割分担の設計","summary":"個人開発のブラウザゲームにAI秘書を導入する際、無料枠の制限を考慮して「AIに任せないこと」を先に決めた事例。ゲームの核となるデータや操作はボタン操作とし、AIは相談役という補助的な役割に限定することで、AIが利用できない環境でもゲーム性を維持する設計とした。\n\nサーバー側でAPIキーの有無を判定し、機能を動的に切り替える実装により、コストとユーザー体験のバランスを最適化している。","importance":7},{"title":"Lean verification of the Riemann Hypothesis","url":"https://leanprover-community.github.io/blog/posts/riemann-hypothesis/","source":"Hatena","published_at":"2026-11-22 01:27","genre":"other","genre_label":"総合・その他IT","headline":"リーマン予想の証明がLeanで検証完了、数学界の歴史的転換点","summary":"Levent Alpöge氏が発表したリーマン予想の証明が、証明支援系「Lean」を用いてコミュニティにより正当性が検証された。約1,737万行のコードが複数の独立したカーネルでコンパイル・受理され、数学的命題との一致も確認済みである。\n\nプログラムの文法的な正しさを超え、Leanの標準公理のみを用いた証明として受理された事実は、形式手法による数学的証明の信頼性を決定づける歴史的な出来事となった。","importance":10},{"title":"54分かかったCIをブラウザテストの4分割で23分にした。2週間後は26分前後に戻った","url":"https://zenn.dev/nishi0001/articles/ci-browser-test-split-54-to-23","source":"Zenn","published_at":"2026-11-21 22:24","genre":"web","genre_label":"Web開発・言語","headline":"CIのブラウザテストを4分割して待ち時間を短縮した事例とその後","summary":"CIの実行時間が54分に達したため、ブラウザテストを4台の並列ジョブに分割して23分まで短縮した事例。分割による待ち時間の短縮効果は大きいが、ジョブのオーバーヘッドにより合計実行時間は微増した。\n\nまた、必須チェックの判定漏れを防ぐための集約ジョブの設計や、時間が経過するにつれてテストの偏りにより実行時間が再び伸びるという、CI運用のリアルな課題と対策が記録されている。","importance":7},{"title":"ソフトウェアファクトリーとコード設計と顧客価値","url":"https://kosui.me/posts/2026/11/15/code-design-after-agents","source":"Hatena","published_at":"2026-11-21 09:35","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI時代のソフトウェア開発：コード設計が顧客価値に直結する理由","summary":"AIエージェントによる開発自動化が進む中で、あえてコード設計を重視する意義を説いた記事。開発速度が向上した現代において、差別化要因は「機能適合性」という品質にあり、人とAIがビジネスロジックを把握しやすい設計が不可欠であると主張しています。\n\n医療系プラットフォームのテックリードとしての経験から、複雑な業務シナリオをコードに正しく反映させる重要性を強調。開発速度よりも「顧客の認知負荷」を律速要因と捉え、PRD（製品要求仕様書）とコード構造を一致させるための設計アプローチの重要性を説いています。","importance":8},{"title":"ISUCONを Muse にやらせてみた：計測と実装を任せた8時間の記録｜バックエンドエンジニア・H執筆","url":"https://zenn.dev/oursship_blog/articles/ff9cdb2e04e781","source":"Zenn","published_at":"2026-11-22 02:19","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ISUCONをAIエージェント「Muse」に任せて挑んだ8時間の記録","summary":"Webアプリの性能改善を競うISUCONに、AIエージェント「Muse」を活用して挑んだ実録。計測・分析・実装・デプロイをAIに任せ、人間は方針判断とベンチマーク実行に集中する分担でスコアを大幅に向上させた。\n\n自作ツール「isucon-kit」でログ集計を自動化し、AIとの連携を最適化した点が勝因。AIによるコード解析が許可された環境下で、計測に基づいた着実なチューニングをAIとどう進めるかの実践的な知見が示されている。","importance":9},{"title":"\"リーマン予想の証明\"の検証は現在どこまで進んでいるか｜加藤文元","url":"https://note.com/katobungen/n/n9c2bb939b9c7","source":"Hatena","published_at":"2026-11-21 22:55","genre":"other","genre_label":"総合・その他IT","headline":"リーマン予想証明の検証状況：Leanによる形式的証明の信頼性","summary":"リーマン予想の証明発表を受け、Leanを用いた第三者検証の進捗を整理。複数の独立したカーネルによる検証が短期間で完了し、証明の正当性が極めて高い信頼度で確認されている現状を解説。\n\n形式的証明が数学界の歴史を塗り替える可能性を示唆しつつ、証明の「正しさ」と「意図する命題との一致」という二つの観点から、現在の検証プロセスの重要性を論じている。","importance":10},{"title":"Windows のネットワーク監視を自作する — 第2回：ETW へ移行する ― プロセス名解決の落とし穴","url":"https://zenn.dev/mojabes_sec/articles/c8e8403a60818e","source":"Zenn","published_at":"2026-11-21 22:21","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Windowsネットワーク監視：ETW移行で見えたプロセス名解決の罠","summary":"ポーリング方式の限界を打破するため、ETW（Event Tracing for Windows）を用いたネットワーク監視ツール「EtwWatch」への移行記録。イベント取得の仕組みを解説しつつ、短命なプロセスが終了した後に名前解決を試みることで発生する「プロセス名が取れない」問題への対策を詳述。\n\nプロセステーブルを自前で維持する設計の重要性と、ライブラリの仕様誤認といった開発中の失敗談を交え、監視ツール開発の勘所を伝えている。","importance":8},{"title":"温度センサーと脱獄 Kindle で、お天気ダッシュボードを作ってみた","url":"https://zenn.dev/zakkie/articles/c99167d7d037d5","source":"Zenn","published_at":"2026-11-21 10:33","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"脱獄KindleとESP32で構築する屋外温度・天気ダッシュボード","summary":"屋外温度センサーのデータをESP32で受信し、Cloudflare WorkersとD1を介して脱獄したKindleに表示するダッシュボードの構築事例。Kindleを電子ペーパーディスプレイとして活用し、天気予報と気温を定期的に更新する仕組みを構築しています。\n\n技術的には、315MHz帯のパルス解析やCloudflare WorkersのCPU時間制限（10ms）への対策として、ヘッドレスChromeによる画像生成を採用する工夫が光ります。無料枠を最大限活用し、低コストで実用的なIoT環境を構築するプロセスが詳細に記録されています。","importance":7},{"title":"堅牢な受け入れテストを書くには？","url":"https://zenn.dev/yasuakiomokawa/articles/3ac970c3a3a1c7","source":"Zenn","published_at":"2026-11-21 18:09","genre":"web","genre_label":"Web開発・言語","headline":"AIコーディングエージェントに堅牢なテストを書かせる4手順","summary":"AIエージェントにテストを書かせると実装変更で壊れやすいテストが生成されがちです。これを防ぐため、外から見える振る舞いのみを基準にする、実装の詳細を基準に含めない、既存のテスト形式に倣う、といった4つの手順が提唱されています。\n\nテストを「凍結」して書き換えを禁止するのではなく、テストの書き方そのものを改善することで、エージェントの柔軟性を活かしつつ保守性の高いテストを維持する手法が解説されています。","importance":7},{"title":"新宿駅で財布を忘れて家に帰れない女の子から「PayPay1000円分を現金で交換して貰えませんか？」とお願いされ、「返さなくていいよ」と1000円あげたら喜ばれず戸惑っていた","url":"https://togetter.com/li/2773268","source":"Hatena","published_at":"2026-11-21 21:31","genre":"other","genre_label":"総合・その他IT","headline":"新宿駅で発生したPayPay送金詐欺の手口と対策","summary":"新宿駅周辺で「財布を忘れた」と称し、PayPay残高と現金の交換を持ちかける詐欺被害が報告されています。被害者は善意で送金するものの、相手は情報を抜き取るか、あるいは金銭を騙し取る目的で近づいている可能性が高いと指摘されています。\n\n警察が交通費を貸し出す制度は地域や状況により対応が異なるため、安易に送金せず、交番へ案内するなどの冷静な対応が推奨されています。知らない相手との金銭のやり取りは避け、トラブルに巻き込まれないよう注意が必要です。","importance":5},{"title":"スシロー、アメリカ・ニューヨーク1号店が大行列の人気「チップ不要なシステムも好評の理由」→アメリカ人も面倒くさいと思ってるのかよ…","url":"https://togetter.com/li/2773198","source":"Hatena","published_at":"2026-11-21 15:18","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"スシローNY店がチップ不要で大行列の人気","summary":"スシローのニューヨーク1号店が、チップ不要の価格体系を採用し、現地で大きな注目を集めています。スタッフの報酬を料金に含める仕組みが好評で、チップ文化に疲弊している現地客からも支持されています。\n\n自動化された接客システムと、チップ不要という明朗会計が、アメリカの飲食店文化に対する新しい選択肢として受け入れられています。インフレ下でも行列ができる人気ぶりは、サービスと報酬のあり方に対する消費者の意識変化を示唆しています。","importance":6},{"title":"「AIが私を追い越した」　リーマン予想「証明」の数学者自身も驚き：朝日新聞","url":"https://www.asahi.com/articles/ASVCP2WB0VCPDIFI008M.html","source":"Hatena","published_at":"2026-11-21 19:01","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIの支援で数学の難問「リーマン予想」を証明か","summary":"米国の数学者が、AIの力を借りて167年来の難問である「リーマン予想」を証明したと発表し、数学界に大きな衝撃を与えています。リーマン予想は素数の分布に関する未解決問題であり、その証明は現代数学における最大の目標の一つです。\n\nAIが数学的推論や証明のプロセスをどこまで代替・加速できるかという議論が活発化しています。今回の発表が正当な証明として認められるか、今後の検証結果が注目されています。","importance":9},{"title":"形式検証を活用した脆弱性診断LLMのプロトタイプをEthereum Foundationに納品｜Nyx Foundation","url":"https://note.com/nyxfoundation/n/n782d4fb32344","source":"Hatena","published_at":"2026-11-21 16:28","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"形式検証を活用した脆弱性診断LLM「SPECA」","summary":"Nyx Foundationが開発した「SPECA」は、仕様書からセキュリティプロパティを抽出し、形式検証とLLMを組み合わせて脆弱性を診断するツールです。Lean 4を用いて重要な性質を形式化し、それを診断項目へ接続することで、精度の高い脆弱性診断を実現しています。\n\nEthereum Foundationの助成を受けて開発され、過去の脆弱性データセットを活用して診断項目を具体化する仕組みを備えています。抽象的な仕様を実装レベルのチェック項目へ落とし込むことで、診断の網羅性と根拠の明確化を図っています。","importance":8},{"title":"一番無難じゃないキャラが優勝　Suica「B案」とAI時代の愛されかた","url":"https://www.watch.impress.co.jp/docs/topic/watchplus/2157644.html","source":"Hatena","published_at":"2026-11-21 11:31","genre":"other","genre_label":"総合・その他IT","headline":"Suica新キャラ「B案」が選ばれた理由とAI時代","summary":"Suicaの次期キャラクターに、最も奇抜で「無難ではない」B案が選ばれました。SNSでの二次創作のしやすさや「余白」の多さが、現代の共感を生むデザインとして高く評価されました。\n\n選考委員からは、AIが何でも答えてくれる時代において、あえて「話しかけたくなる鏡」のような存在としてのキャラクターの重要性が語られました。Suicaが単なる決済デバイスから、人々の心の拠り所となる存在へ進化することへの期待が込められています。","importance":5},{"title":"初心者がAIとMAXのAPKを解析してみた【後編】","url":"https://zenn.dev/aki0804/articles/ac6690df48a1ae","source":"Zenn","published_at":"2026-11-21 17:44","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Androidアプリ「MAX」のAPK解析と通信調査","summary":"Androidアプリ「MAX」のAPKを解析し、FridaやADBを用いて実行時の通信や端末識別子の挙動を調査した記録の後編です。登録画面での通信内容や、環境設定変更に対するアプリの追従性を検証しています。\n\n暗号化された通信のUID照合や、データ消去後の識別子変化などを詳細に記録しており、AIエージェントの補助を活用した解析手法が示されています。正規ログイン後の検証には至りませんでしたが、アプリの内部構造を理解するための実践的な調査プロセスがまとめられています。","importance":5},{"title":"BlenderのGPUアクセラレーション対応UIを他のアプリケーションから再利用可能にする「BUI」","url":"https://gigazine.net/news/20261121-bui/","source":"Hatena","published_at":"2026-11-21 12:24","genre":"web","genre_label":"Web開発・言語","headline":"BlenderのUIを他アプリで再利用する「BUI」","summary":"「BUI」は、Blenderの洗練されたUIを独立したライブラリとして移植し、他のアプリケーションから利用可能にするプロジェクトです。C言語製のコアを持ち、Python、Rust、JSなど多様な言語からバインディングを通じて利用できます。\n\nダメージレンダリングによる高いパフォーマンスと、Blender特有の直感的な操作感を再現しています。ブラウザエンジンに依存せず、ネイティブ環境でWebライクなUIを構築できるため、効率的なUI開発を求める開発者にとって強力なツールとなりそうです。","importance":7},{"title":"S&P500が調整局面入り　「重なる最悪の事態」AI株高ピーク過ぎたか - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOFL20CUL0Q6A121C2000000/","source":"Hatena","published_at":"2026-11-21 08:11","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"S&P500調整局面入り：AI株高のピークアウト懸念","summary":"米国株式市場において、S&P500種株価指数が調整局面入りしたことを報じた記事。エヌビディアの好決算やアンソロピックの新規上場といったポジティブなニュースがあっても株価が下落しており、AI関連銘柄への熱狂がピークを過ぎた可能性を示唆しています。\n\n市場ではデータセンター建設の不透明感や、AI以外のセクターへの資金シフトが議論されており、投資家の温度差が広がっています。AI主導の相場が転換点を迎えている可能性について、市場の動向を分析しています。","importance":7},{"title":"【TLA+】AIにテストケースを書かせるな。ルールを書け","url":"https://zenn.dev/karamage/articles/73027ee36796dc","source":"Zenn","published_at":"2026-11-21 11:12","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI時代のテスト戦略：ケースを書くのではなくルールを定義せよ","summary":"AIがコードとテストを同時に生成する時代において、従来のテストケース作成手法が抱える「自作自演の満点」という限界を指摘した記事。AIにテストを任せると、実装のバグをテスト側も同様に見逃すリスクがあるため、人間は「テストケース」ではなく「守るべきルール」を定義すべきだと提唱しています。\n\n解決策として、TLA+やQuintといった形式検証言語を用いたモデル検査を紹介。チケット販売システムを例に、状態遷移と不変条件（ルール）を記述することで、人間が網羅しきれないエッジケースを機械的に検証する手法を解説しています。AI時代におけるエンジニアの役割は、仕様の「採点基準」を設計することにシフトすべきという結論です。","importance":9},{"title":"「パッチ地獄」が米IT障害誘発、AIがせかす脆弱性修正　銀行や空港停止 - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOGN18CYM0Y6A111C2000000/","source":"Hatena","published_at":"2026-11-21 09:21","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AIによる脆弱性発見の加速とパッチ適用に追われるインフラの危機","summary":"AIが膨大な脆弱性を短期間で発見するようになったことで、企業がパッチ適用に追われ、結果としてシステム障害を誘発している現状を報じた記事。マイクロソフトや金融機関などで相次ぐ障害の背景には、AIによる攻撃の民主化と、修正作業の過負荷という構造的な問題があります。\n\nAIは防御側だけでなく攻撃側にも活用されており、脆弱性検知から悪用までの猶予期間が極端に短縮されています。日本のインフラも同様のリスクに晒されており、多段階の防御策や自動化されたセキュリティ運用の重要性が高まっています。","importance":9},{"title":"令和8年に「INFOBAR」が復活するも、通話とSMSしかできない「ダムフォン」に","url":"https://www.itmedia.co.jp/mobile/articles/2611/21/news011.html","source":"Hatena","published_at":"2026-11-21 15:49","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"INFOBARが通話・SMS専用のダムフォンとして復活","summary":"KDDIの「INFOBAR ZERO」が、WebブラウジングやSNS機能を排除した「ダムフォン」として復活しました。デジタルデトックスを目的とし、音声通話とSMSのみに対応したSIMロックフリー端末として、2026年12月に発売されます。\n\n現代の若者にとってSNSのない環境は極端なデトックスになる可能性も指摘されていますが、スマートフォンの便利さとシンプルなケータイの使い分けを提案する新しい試みです。デザイン性を重視しつつ、あえて機能を絞ることで新たな価値を模索しています。","importance":5},{"title":"Safari で contentEditable に focus() するとページ先頭へ飛ぶ問題の対処まとめ","url":"https://zenn.dev/qqpann/articles/safari-contenteditable-focus-scroll-jump","source":"Zenn","published_at":"2026-11-22 02:35","genre":"web","genre_label":"Web開発・言語","headline":"SafariでcontentEditableにフォーカスするとページ先頭へ飛ぶ問題の対処","summary":"SafariにおいてcontentEditable要素へfocus()した際にページが先頭へスクロールしてしまう現象に対し、ブラウザの自動スクロールを抑制する手法を解説。focus({ preventScroll: true })を使用し、必要に応じてscrollIntoViewで位置を微調整するアプローチが有効である。\n\nただし、タッチ端末ではキーボード追従を阻害する可能性があるため、環境に応じた条件分岐が必要となる。自動テストでの再現が困難なケースにおける、実環境での目視検証の重要性も強調されている。","importance":6},{"title":"作れるエンジニアから、価値を届けるエンジニアへ","url":"https://zenn.dev/kubell/articles/3c3490a3592bb1","source":"Zenn","published_at":"2026-11-21 00:50","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"エンジニアの役割拡大：作る人から価値を届ける人へ","summary":"AIの活用により実装コストが低下した今、エンジニアが「何を作るか」という意思決定に関与し、価値を届ける存在になるべきだと説いた記事。ターゲット選定、ペインの特定、体験価値の設計という3つの観点から、エンジニアが役割を広げるためのフレームワークを提案しています。\n\n「大盛り無料にしてほしい」という要望の裏にある真の価値を捉えるなど、ユーザーの要望を鵜呑みにせず、抽象度を調整して本質的な課題を解決するアプローチを推奨。エンジニアがプロダクトの意思決定に深く関わることで、より高い価値を生み出せるという視点を共有しています。","importance":7},{"title":"ローカルLLMでクラウドのトークンを9割節約する","url":"https://zenn.dev/ace_toshi/articles/local-llm-confidential-mapreduce","source":"Zenn","published_at":"2026-11-22 00:45","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ローカルLLMとMap-ReduceでクラウドAPIのトークンを9割節約","summary":"議事録要約などの非本質的なタスクにクラウドLLMのトークンを消費することに疑問を感じ、ローカルLLMへ処理を移行した事例。長文を扱うためにMap-Reduce手法を採用し、行の分断防止や文脈の参照専用化といった設計要件を実装することで、精度を維持しつつクラウド利用量を大幅に削減した。\n\nこの構成は、セキュリティ要件で外部APIを利用できない環境でのLLM活用にもそのまま転用可能である。","importance":8},{"title":"相次ぐシステム障害、AIはどこまで関係しているのか--「12月はさらに深刻に」と専門家","url":"https://japan.cnet.com/article/35255244/","source":"Hatena","published_at":"2026-11-21 08:39","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AIがもたらす「脆弱性の洪水」とインターネットの脆弱化","summary":"相次ぐシステム障害の背景に、AIによるハッキングの民主化と脆弱性発見の自動化があることを解説した記事。かつては専門家が必要だった攻撃が、AIツールによって若年層でも実行可能になり、攻撃の頻度と範囲が劇的に拡大しています。\n\n「vulnpocalypse（脆弱性の終末）」という造語が示す通り、あまりに多くの脆弱性が発見されるため、管理者が修正に追いつけない状況が続いています。AIが生成したコードの品質問題も重なり、インターネット基盤全体の危うさが浮き彫りになっています。","importance":9},{"title":"日本でも「ダムフォン」は広がるか？　KDDIが「INFOBAR ZERO」で目指す2台持ちの新しい形","url":"https://www.itmedia.co.jp/mobile/articles/2611/21/news010.html","source":"Hatena","published_at":"2026-11-21 06:20","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"KDDI「INFOBAR ZERO」が目指すデジタルデトックスと2台持ち","summary":"KDDIが発売する通話とSMSに特化した「INFOBAR ZERO」を通じた、ダムフォン市場への挑戦とデジタルデトックスの潮流を解説した記事。スマホ依存やSNS疲れに対するアンチテーゼとして、あえて機能を絞り込んだ端末を提案しています。\n\nスマホとの2台持ちを前提とし、セカンドナンバーサービスやeSIM対応など、利便性を損なわない工夫が施されています。KDDIの狙いは大きな市場シェアではなく、ブランド価値の向上と新しいライフスタイルの提案にあり、デジタル時代における「つながり方」の再定義を試みています。","importance":6},{"title":"無料でセルフホストできWindows・macOS・LinuxアプリもあるRSSリーダー「WyrmRSS」、YouTube動画の再生やDiscord・Slackへの新着通知も可能","url":"https://gigazine.net/news/20261121-wyrmrss/","source":"Hatena","published_at":"2026-11-21 23:01","genre":"web","genre_label":"Web開発・言語","headline":"セルフホスト可能なRSSリーダー「WyrmRSS」の機能と活用法","summary":"YouTube動画再生やWebhook通知にも対応したオープンソースのRSSリーダー「WyrmRSS」の紹介。セルフホストおよびデスクトップアプリとして利用可能で、フィードごとの表示モード設定や高度なフィルタリング機能が特徴。\n\n特にYouTubeのShorts除外や、Discord/Slackへの新着通知機能は、情報収集の効率化を求めるエンジニアにとって実用性が高い。インストールから設定まで、その多機能性が高く評価されている。","importance":6},{"title":"KARTEを選んだのは顧客の私じゃない｜しがないサラリーマン","url":"https://note.com/kochan34123412/n/nf37511e42de9","source":"Hatena","published_at":"2026-11-21 07:36","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"KARTE情報漏えい：企業が「選んだ責任」をどう説明すべきか","summary":"KARTEの脆弱性を突いた不正アクセスによる情報漏えいを受け、利用企業各社の発表文を分析した論考。各社が「外部サービスでの事故」として説明する中で、顧客情報の連携範囲や選定理由についての説明が不足している点を指摘しています。\n\n企業が外部サービスを選定し、どの情報を連携するかを決定した責任は、事故発生後も続くべきだと主張。単なる謝罪ではなく、なぜその情報を連携していたのか、その妥当性をどう検証するのかという「選んだ側の言葉」を求める顧客の視点を提示しています。","importance":6},{"title":"GitHub - mitaku/andon: A one-person software factory: AI coding agents take tasks from a ledger through review to merge, and call the human only for decisions only they can make.","url":"https://github.com/mitaku/andon","source":"Hatena","published_at":"2026-11-21 19:52","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントによる一人ソフトウェア工場「Andon」","summary":"「Andon」は、AIエージェントが課題の実装からレビュー、マージまでを自律的に行う、一人で運用可能なソフトウェア工場システムです。トヨタ生産方式の「アンドン」に着想を得ており、人間は重要な意思決定のみに関与する「選択的ダークファクトリー」を目指しています。\n\nプロジェクトごとに独立したコンテナ（セル）内でエージェントが連携し、ファイルベースの課題管理を行う仕組みです。人間が介入すべき判断を最小限に絞ることで、開発効率の最大化を図る新しい開発スタイルを提案しています。","importance":8},{"title":"Apache Iceberg v4の仕様を読んで、何が変わるのか考えてみた","url":"https://zenn.dev/penginpenguin/articles/5a04e281b16a68","source":"Zenn","published_at":"2026-11-21 23:33","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Apache Iceberg v4仕様：メタデータ構造の刷新と運用負荷の軽減","summary":"開発中のApache Iceberg v4仕様を読み解き、運用負荷軽減に向けた変更点を解説。manifest listを廃止しroot manifestへ統合する構造や、データファイルと削除情報の管理一体化が注目点である。\n\n特にequality deleteの新規書き込み廃止は現場への影響が大きい。v4は新機能追加よりも、ストリーミング処理などで増大しがちなメタデータ管理の複雑さを仕様側で吸収しようとする意図が読み取れる。","importance":7},{"title":"ボールの慣性で素早いカーソル移動！奥深きトラックボールの世界 3つのスタイルに分けて計14モデルをピックアップ text by 石川 ひさよし","url":"https://akiba-pc.watch.impress.co.jp/docs/sale/online_shopping/2158378.html","source":"Hatena","published_at":"2026-11-21 10:24","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"トラックボールの選び方：3つのスタイルと推奨モデル14選","summary":"PC操作の効率化や省スペース化に貢献するトラックボールについて、操作スタイル別に特徴と推奨モデルを紹介した記事。人差し指操作型と親指操作型の違いを軸に、Kensingtonやエレコムなどの主要メーカーの製品をピックアップしています。\n\nボールの慣性を活かした素早いカーソル移動や、ボタン配置によるカスタマイズ性など、マウスとは異なるトラックボール特有のメリットを解説。用途に応じた最適なデバイス選びの指針として、初心者から玄人まで参考になるカタログ的な内容です。","importance":4},{"title":"Go の defer についてちょっと調べてみた ── 3つの実装方式","url":"https://zenn.dev/wakame_atsushi/articles/f2f7512d5e0f87","source":"Zenn","published_at":"2026-11-21 11:19","genre":"web","genre_label":"Web開発・言語","headline":"Go言語のdefer実装：3つの方式とスタックフレームの仕組み","summary":"Go言語におけるdeferの仕組みを、ランタイムのソースコードとコンパイラの出力から解説した記事。deferには「後で呼ぶ内容を保存する」登録段階と「保存した内容を呼び出す」実行段階があり、その実装方式はコンパイル時の解析結果によって3つに分類されます。\n\n具体的には、_defer構造体を用いたリスト管理や、スタックフレームの境界を判定するsp（スタックポインタ）の役割について詳述しています。特に、ループ内でのdefer登録やgoroutineごとのスタック管理など、Goのランタイムがどのように効率的に後始末処理を実現しているかが理解できる内容です。","importance":6},{"title":"イーロン・マスクが金持ちでもそんなネットで嫌われてないのって「男の子がワクワクするもの」に迷わず巨額の金を突っ込むからだと思うんだよな","url":"https://togetter.com/li/2773122","source":"Hatena","published_at":"2026-11-21 12:06","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"イーロン・マスクが支持される「少年のような情熱」","summary":"イーロン・マスク氏が富豪でありながらネット上で一定の支持を得ている理由は、彼が「男の子がワクワクするもの」に迷わず巨額の資金を投じているからだという分析が話題です。\n\n宇宙開発や自動運転など、SFのような夢を本気で実現しようとする姿勢が、オタク的な情熱と重なり、多くの共感を生んでいます。単なる豪遊ではなく、技術を未来へ繋げるための投資を行う姿が、少年漫画の主人公のように映ることが、彼特有のカリスマ性を支えているようです。","importance":4},{"title":"S3 Vectorsで日本語FAQ検索を試したメモ","url":"https://zenn.dev/hiroyannnn/articles/s3-vectors-japanese-faq-search","source":"Zenn","published_at":"2026-11-21 23:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"S3 Vectorsを用いた全文・ベクトル検索のハイブリッド検索検証","summary":"AWSのS3 Vectorsを活用し、全文検索とベクトル検索を組み合わせたハイブリッド検索の性能を検証したメモ。RRF（Reciprocal Rank Fusion）による順位統合の効果を、FAQデータを用いて測定した。\n\nベクトル検索は意味的な検索に強く、全文検索はキーワード一致に強いという特性を活かし、カテゴリ絞り込みと組み合わせることで検索精度を向上させる実践的な構成が示されている。","importance":7},{"title":"GoogleやAppleなどのアカウント乗っ取りでPayPay不正利用の事例　サポートが注意喚起","url":"https://www.itmedia.co.jp/mobile/articles/2611/20/news069.html","source":"Hatena","published_at":"2026-11-20 22:10","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"外部アカウント乗っ取りによるPayPay不正利用への注意喚起","summary":"Google、Apple、Yahoo!JAPANなどのアカウントが乗っ取られ、連携しているPayPayが不正利用される被害が確認されたことを受けた注意喚起記事。PayPay側での検知が困難なケースであるため、連携先アカウントのセキュリティ対策が重要視されています。\n\n二段階認証の設定やパスワードの使い回し禁止など、ユーザー側で講じるべき対策を解説。PayPay側の補償制度や、本人確認（eKYC）の強化といったセキュリティ向上への取り組みについても触れられており、キャッシュレス決済におけるアカウント管理の重要性が強調されています。","importance":8},{"title":"git ls-files -z の出力に trim() を掛けて、先頭が空白のファイルを検査から落としていた","url":"https://zenn.dev/nishi0001/articles/git-ls-files-z-trim-leading-space","source":"Zenn","published_at":"2026-11-21 22:49","genre":"web","genre_label":"Web開発・言語","headline":"git ls-filesの出力にtrim()を掛けてファイルを見落とすバグの修正","summary":"CIの検査スクリプトにおいて、git ls-files -zの出力にtrim()を適用したことで、空白で始まるファイル名が加工され、存在しないファイルとして読み落とされていたバグの解説。修正として、メールアドレスなど必要な箇所のみにtrim()を限定し、ファイルパスの加工を廃止した。\n\nまた、読めなかったファイルを黙って無視するcatchブロックの危険性についても触れ、堅牢なスクリプト設計の重要性を説いている。","importance":5},{"title":"PHPカンファレンス関西2026のお誘いチケットを学生・若手エンジニアの方へ先着2名に譲渡します - おうさまのみみはロバのみみ","url":"https://luccafort.hatenablog.com/entry/2026/11/20/193344","source":"Hatena","published_at":"2026-11-20 20:54","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"PHPカンファレンス関西2026、学生・若手エンジニア向けチケット譲渡の取り組み","summary":"2027年1月開催の「PHPカンファレンス関西2026」に向け、運営者が学生や新卒3年目までの若手エンジニアを対象に、費用負担なしで参加できる「お誘いチケット」の譲渡を呼びかけています。地域コミュニティの活性化と、カンファレンスのテーマである「まわりを巻き込む」ことを目的としています。\n\n金銭的・心理的な参加ハードルを下げることで、これまでイベントに参加したことがない層を呼び込み、コミュニティの新たな仲間を増やす狙いがあります。応募は先着順で、技術コミュニティの交流を促進するユニークな試みです。","importance":3},{"title":"RTX 4070 12GBでLLMを5モデル×520試行――再現性を監査してわかったこと","url":"https://zenn.dev/shinyahayakawa/articles/8d3892e901340a","source":"Zenn","published_at":"2026-11-21 21:11","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"RTX 4070でLLMの再現性を監査した実験報告","summary":"ローカルLLMの実験において、「モデルが動くこと」と「研究に耐えうる結果を得ること」は別物であるという視点から、RTX 4070（VRAM 12GB）環境で5モデル計2,600試行の再現性検証が行われました。\n\n実験ではOllamaのバージョンやdigestの固定、実行ハーネスの整備により、後から監査可能な記録を残す手法が示されました。単なる性能比較ではなく、実行条件の厳密な管理と再現性の確保が、信頼性の高いLLM研究には不可欠であると結論づけています。","importance":7},{"title":"攻撃元IPを止めても終わらない","url":"https://zenn.dev/12ban/articles/attack-infra-hunting-01-pyramid-of-pain","source":"Zenn","published_at":"2026-11-20 11:28","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"IPブロックだけでは不十分、攻撃者の「指紋」で防ぐセキュリティ対策","summary":"Webサービス運用における攻撃元IPのブロックリスト運用が、なぜ「もぐらたたき」に終わるのかを解説しています。攻撃者はIPを容易に変更できるため、IPベースの防御には限界があるという指摘です。\n\n「Pyramid of Pain」の概念に基づき、攻撃者にとって変更が困難な「TTP（戦術・技術・手順）」やサーバーの「指紋」に着目した防御の重要性を説いています。公開データを用いた分析により、より本質的なセキュリティ対策の考え方を提示しています。","importance":8},{"title":"AIが爆速で開発する時代の、自動テストとの向き合い方","url":"https://zenn.dev/daiaoki/articles/webterm-ai-era-testing","source":"Zenn","published_at":"2026-11-19 16:11","genre":"web","genre_label":"Web開発・言語","headline":"AI開発時代における自動テストの重要性と品質担保の戦略","summary":"AIによる高速なコード生成が当たり前になる中で、個人開発サービスにおいてどのように自動テストを育て、品質を維持しているかを解説しています。1日100コミットを超える開発環境において、自動テストは不可欠な存在です。\n\nTypeScriptによるブラウザ内シミュレーターの構築や、副作用のない「Functional Core」の設計など、テストしやすいコードベースを維持する工夫が紹介されています。AIに開発を任せるからこそ、テストによる品質保証が重要になるという視点です。","importance":7},{"title":"Welcome! You are invited to join a webinar: 【26/11/26開催】「脱WordPress」に取り組みたい方へ。セキュリティ懸念・運用負担を解消するSaaS型CMS移行. After registering, you will receive a confirmation email about joining the webinar.","url":"https://hatena.zoom.us/webinar/register/2217624929911/WN_UyuXGu7hRfSejKa5G_lUGg","source":"Hatena","published_at":"2026-11-19 11:00","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"WordPressのセキュリティ懸念を解消するSaaS型CMS移行セミナー","summary":"WordPress運用におけるセキュリティリスクや運用負荷に悩む企業担当者向けに、SaaS型CMSへの移行をテーマにしたセミナーの案内です。WordPressの脆弱性対応や外注依存による更新の遅れを解消する移行先の選び方を解説します。\n\n情シス部門と現場の要望を両立させるための移行プロセスや、管理画面の操作デモを通じて、運用担当者がいかに業務を効率化できるかを提示します。脱WordPressを検討している企業にとって有益な情報提供の場となっています。","importance":4},{"title":"GitHub - fkubota/understand-mode: Claude Code の出力・PR・コードを、付箋のホワイトボードで寄り道しながら理解する /understand スキル","url":"https://github.com/fkubota/understand-mode","source":"Hatena","published_at":"2026-11-21 18:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeの理解を深める付箋UI「/understand」","summary":"「understand-mode」は、Claude Codeの出力やPR、コードをホワイトボード上の付箋形式で視覚的に理解するためのツールです。わからない箇所を選択して付箋を作成すると、メインの文脈を引き継いだ分身が回答し、本筋の会話を汚さずに調査を進められます。\n\nMermaidによる図解やSQL実行結果の表示にも対応しており、複雑なコードベースの理解やレビューを効率化します。調査終了後は必要な情報をメインの会話に反映できるため、開発者の思考プロセスを強力にサポートします。","importance":7},{"title":"相次ぐOSSの脆弱性に、とりあえずクラウドWAF入れるだけでだいぶ違う話+Rootlessコンテナもいいぞ","url":"https://zenn.dev/kusuke/articles/98e178e6824cac","source":"Zenn","published_at":"2026-11-19 10:34","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"相次ぐOSS脆弱性への対策、クラウドWAF導入とRootlessコンテナの推奨","summary":"PHPやJava、nginxなど、ランタイムやWebサーバーの根幹に関わる脆弱性が相次ぐ中、パッチ適用までの期間を凌ぐための現実的な対策を提案しています。特にクラウドWAFの導入による通信終端の重要性を説いています。\n\nWAFはSQLi対策だけでなく、プロトコルレベルの攻撃やレート制限による防御に有効です。また、セキュリティ向上のためにRootlessコンテナの利用も推奨しており、エンジニアが深夜のパッチ作業から解放されるためのアーキテクチャ上の保険を提唱しています。","importance":9},{"title":"[Rust] clap で引数か標準入力のどちらかでファイルを受け取る","url":"https://zenn.dev/00_4/articles/rust-clap-file-input","source":"Zenn","published_at":"2026-11-21 19:30","genre":"web","genre_label":"Web開発・言語","headline":"Rustのclapで引数と標準入力を両立する方法","summary":"RustのCLIツール開発において、clapクレートを使用して「ファイルパス引数」と「標準入力」の両方からデータを受け取れるようにする実装手法が解説されています。\n\n引数をOption<PathBuf>として定義し、Noneの場合に標準入力を読み込む設計が基本です。さらに、POSIXの慣習に従い「-」を標準入力として扱う実装を加えることで、パイプラインとの親和性が高い、使い勝手の良いCLIツールを実現する方法が紹介されています。","importance":4},{"title":"Introducing Inkling 2 Mini","url":"https://thinkingmachines.ai/news/inkling-2-mini/","source":"Hatena","published_at":"2026-11-21 08:08","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ノートPCで動作する高性能モデル「Inkling 2 Mini」公開","summary":"ノートPCで動作可能な軽量かつ高性能なオープンウェイトモデル「Inkling 2 Mini」のリリース情報。中間層を3回ループさせる「looped transformer」アーキテクチャを採用し、少ないトークン数で高い推論能力を実現しています。\n\n26.4Bパラメータ（アクティブ3.4B）で、エージェント的なコーディングタスクにおいて既存の100B未満モデルを凌駕する性能を記録。メモリフットプリントは約20GBで、消費者のラップトップでも動作可能です。推論の可視化（CoT）とループ回数の関係性についても実験結果が公開されています。","importance":8},{"title":"ロボットとPLCのログ、3秒ずれると先に見える異常が変わる","url":"https://zenn.dev/nagi_lab/articles/0e86158fcdd169","source":"Zenn","published_at":"2026-11-22 00:03","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ロボットとPLCのログ時刻ずれを補正し、異常の因果関係を可視化する","summary":"異なるシステム（ロボットとPLC）のログを統合する際、時計のわずかなずれが異常発生順序の誤認を招く問題について解説。共通のマーカー信号を利用して時刻差を算出し、補正を行うことで正確な時系列を再現する手法を提示した。\n\n実現場におけるログの目印の選び方や、クロック変動を考慮した慎重な分析の重要性を説いており、製造現場のエンジニアにとって示唆に富む内容となっている。","importance":6},{"title":"DOTweenを使わずにイージングを自作する！Robert Pennerのイージング関数をC#で実装して検証してみた","url":"https://zenn.dev/sorane/articles/e1ed930dea9b1d","source":"Zenn","published_at":"2026-11-21 01:03","genre":"web","genre_label":"Web開発・言語","headline":"DOTweenなしで実現するイージング関数：C#での実装と検証","summary":"Unity等の外部ライブラリを使わずに、Robert Penner氏のイージング関数をC#で自作・実装する方法を解説した記事。イージングは「0〜1の進行度を受け取って値を返す」数式であるため、静的クラス一つで実装可能であることを示しています。\n\n31種類のイージング関数を列挙型で管理し、インスペクターから選択可能にする設計手法を紹介。System.MathFを使用することでUnityエンジンへの依存を排除し、汎用的なC#クラスとして実装する手順を詳述しています。easings.netを活用した検証方法も併せて解説されています。","importance":5},{"title":"寝てる間に自動で動くAIエージェントを誰でも作れる：10分でわかる pstack 実践ガイド","url":"https://zenn.dev/canly/articles/ca6875cd79539f","source":"Zenn","published_at":"2026-11-20 18:04","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Cursor公式スキル「pstack」を活用した自律型AIエージェントの実践ガイド","summary":"Cursor公式のプラグイン集「pstack」を用い、指示から設計、実装、テストまでを人手なしで完走させるAIエージェントの構築手法が解説されています。特に「コンパイルが通った」をゴールにせず、実際のコマンド出力や数値で検証する「深い」アプローチが特徴です。\n\nClaude Codeと組み合わせ、10分程度で高品質なコード生成とテスト検証を自動化するプロセスが示されています。AIが生成するコードの品質を担保し、自律的に作業を完結させるための具体的なプレイブック活用術が学べます。","importance":8},{"title":"検証環境と外の環境を切り分けたいので VyOS を導入してみた。","url":"https://zenn.dev/y_mrok/articles/install_vyos","source":"Zenn","published_at":"2026-11-21 22:40","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"検証環境の分離にVyOSを導入：ルーター構築の基本設定手順","summary":"検証環境と外部ネットワークを論理的に分離するため、VMware上にVyOSを導入してルーターとして構築する手順を解説。インターフェース設定、DHCP、NAT、ファイアウォールの基本設定を網羅している。\n\n検証用途としてRolling Releaseを使用し、LAN/WANの疎通確認までをステップバイステップで紹介。ネットワークの基礎知識を再確認しつつ、安全な検証環境を構築するための実用的なガイドとなっている。","importance":6}]};
